package com.codepilot1c.core.edt.development;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class DirectClientControlsTest {
 private Map<String,Object> action(String name){return new LinkedHashMap<>(Map.of("action",name,"expected_window","Card","snapshot_id","owned","element","Field"));}
 @Test public void typedCommandsPassWithoutWeakeningInput(){for(String n:List.of("check","uncheck","tab","activate","expand","collapse","increase","decrease","open_choices"))DirectTestClientService.validateAction(action(n));var a=action("input");a.put("value",true);assertThrows(IllegalArgumentException.class,()->DirectTestClientService.validateAction(a));}
 @Test public void boundedChoiceAndSlider(){var a=action("choose_value");assertThrows(IllegalArgumentException.class,()->DirectTestClientService.validateAction(a));a.put("value","Choice");DirectTestClientService.validateAction(a);var b=action("set_position");for(Object v:List.of(-1,101,5.5,true,"50")){b.put("position",v);assertThrows(IllegalArgumentException.class,()->DirectTestClientService.validateAction(b));}b.put("position",50.0);DirectTestClientService.validateAction(b);b.put("value",true);assertThrows(IllegalArgumentException.class,()->DirectTestClientService.validateAction(b));}
 @Test public void realCalendarDateAndIrrelevantFields(){var a=action("set_date");for(String d:List.of("2026-02-30","2026-2-03","bad")){a.put("date",d);assertThrows(IllegalArgumentException.class,()->DirectTestClientService.validateAction(a));}a.put("date","2026-02-28");DirectTestClientService.validateAction(a);a.put("position",50);assertThrows(IllegalArgumentException.class,()->DirectTestClientService.validateAction(a));}
 @Test public void checkboxTableCellsAreTypedButRowMatchRemainsText(){var a=new LinkedHashMap<String,Object>(Map.of("action","table_set","table","Lines","expected_window","Card","snapshot_id","owned","row_match",Map.of("Key","A"),"cells",Map.of("Flag",true,"Text","x")));DirectTestClientService.validateAction(a);a.put("row_match",Map.of("Flag",true));assertThrows(IllegalArgumentException.class,()->DirectTestClientService.validateAction(a));a.put("row_match",Map.of("Key","A"));a.put("position",10);assertThrows(IllegalArgumentException.class,()->DirectTestClientService.validateAction(a));}
 @Test public void batchValidatesEveryTypedStepBeforeDispatch(){var one=action("check");one.remove("snapshot_id");var two=action("set_date");two.remove("snapshot_id");two.put("date","2026-02-30");var a=Map.<String,Object>of("action","batch","expected_window","Card","snapshot_id","owned","steps",List.of(one,two));assertThrows(IllegalArgumentException.class,()->DirectTestClientService.validateAction(a));}
 @Test public void calendarUiRunNeedsScalarProofBeforeLaunch(){var step=action("set_date");step.remove("snapshot_id");step.put("date","2026-02-28");step.put("expect",Map.of("window","Card"));var run=Map.<String,Object>of("project","P","base_uuid","00000000-0000-0000-0000-000000000001","idempotency_key","calendar","steps",List.of(step));assertThrows(IllegalArgumentException.class,()->UiRunService.validate(run));step.put("expect",Map.of("fields",Map.of("CalendarEcho","28.02.2026")));UiRunService.validate(run);step.put("expect",Map.of("fields",Map.of("Field","28.02.2026")));assertThrows(IllegalArgumentException.class,()->UiRunService.validate(run));}
}
